/*
   Two strings a and b can correspond under the substitution rule iff:
   - same length
   - for every position i, j:
       a[i] == a[j]  <=>  b[i] == b[j]
   This is exactly the "same pattern" condition.
*/
static int same_pattern(const char *a, const char *b) {
    int la = (int)strlen(a);
    int lb = (int)strlen(b);
    if (la != lb) return 0;

    int ma[256], mb[256];
    for (int i = 0; i < 256; i++) ma[i] = mb[i] = -1;

    for (int i = 0; i < la; i++) {
        unsigned char ca = (unsigned char)a[i];
        unsigned char cb = (unsigned char)b[i];
        if (ma[ca] == -1 && mb[cb] == -1) {
            ma[ca] = cb;
            mb[cb] = ca;
        } else {
            if (ma[ca] != cb || mb[cb] != ca) return 0;
        }
    }
    return 1;
}

int main(void) {
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%s", dict[i].s);
        dict[i].len = (int)strlen(dict[i].s);
    }

    int c;
    while ((c = getchar()) != '\n' && c != EOF) {}

    char line[MAX_LINE];
    while (fgets(line, sizeof(line), stdin)) {
        int first = 1;
        char *tok = strtok(line, " \n");
        while (tok) {
            const char *ans = NULL;
            for (int i = 0; i < n; i++) {
                if (dict[i].len == (int)strlen(tok) && same_pattern(dict[i].s, tok)) {
                    ans = dict[i].s;
                    break;
                }
            }

            if (!first) putchar(' ');
            first = 0;

            if (ans) {
                fputs(ans, stdout);
            } else {
                for (int i = 0; tok[i]; i++) putchar('*');
            }

            tok = strtok(NULL, " \n");
        }
        putchar('\n');
    }

    return 0;
}

