class UnionFind {
public:
    vector<int> parent, rank;
    UnionFind(int n) {
        parent.resize(n);
        rank.resize(n, 0);
        for (int i = 0; i < n; i++) parent[i] = i;
    }
    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx == ry) return;
        if (rank[rx] < rank[ry]) swap(rx, ry);
        parent[ry] = rx;
        if (rank[rx] == rank[ry]) rank[rx]++;
    }
};

string canonical(const string &s, UnionFind &uf) {
    // map each letter to smallest letter in its component
    vector<char> compChar(26, 0);
    for (int i = 0; i < 26; i++) {
        int root = uf.find(i);
        if (compChar[root] == 0) compChar[root] = 'a' + i;
        compChar[root] = min(compChar[root], (char)('a' + i));
    }
    string res;
    for (char c : s) {
        int root = uf.find(c - 'a');
        res.push_back(compChar[root]);
    }
    return res;
}

