// Check if plaintext P can produce ciphertext C given pairs
// pairs: map from letter to its pair (identity if no pair)
bool canProduce(const string& P, const string& C, map<char,char>& partner) {
    if (P.size() != C.size()) return false;
    // For each pair, determine if it's swapped or not
    map<char,char> pairDecision; // canonical char -> 0 (no swap) or 1 (swap)
    for (int i = 0; i < P.size(); i++) {
        char p = P[i], c = C[i];
        char par = partner[p];
        if (p == c) {
            // no swap for this pair
            // check consistency
            if (pairDecision.count(p) && pairDecision[p] != 0) return false;
            if (pairDecision.count(par) && pairDecision[par] != 0) return false;
            pairDecision[p] = 0;
            if (par != p) pairDecision[par] = 0;
        } else if (par == c) {
            // swap for this pair
            if (pairDecision.count(p) && pairDecision[p] != 1) return false;
            if (pairDecision.count(par) && pairDecision[par] != 1) return false;
            pairDecision[p] = 1;
            pairDecision[par] = 1;
        } else {
            return false;
        }
    }
    return true;
}

