/*
The statement provided is incomplete, but it clearly describes the classic task:

- We are given a dictionary of candidate plaintext words.
- Then ciphertext lines follow.
- A ciphertext word can be produced from a plaintext word by a one-to-one substitution cipher.
- For each line, we must recover plaintext words using a consistent substitution over the whole line.
- If no solution exists, output '*' for every letter, preserving spaces.

This matches the well-known "Crypt Kicker" style problem.

Input format assumed:
- First line: integer n, number of dictionary words
- Next n lines: dictionary words
- Remaining lines until EOF: ciphertext lines

Output:
- For each ciphertext line, either the deciphered line or stars replacing letters.

Approach:
- Group dictionary words by length.
- For each ciphertext line, split into words.
- Backtracking over words, assigning cipher->plain and plain->cipher mappings consistently.
- Use word patterns and choose the most constrained word first.
- If solved, decode whole line; otherwise replace letters with '*'.
*/

static vector<int> patternOf(const string& s) {
    unordered_map<char,int> mp;
    vector<int> p;
    int id = 0;
    for(char c : s) {
        if(!mp.count(c)) mp[c] = id++;
        p.push_back(mp[c]);
    }
    return p;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    string tmp;
    getline(cin, tmp); // consume endline

    unordered_map<int, vector<string>> dictByLen;
    unordered_map<string, vector<string>> dictByLenPattern;

    for (int i = 0; i < n; ++i) {
        string w;
        getline(cin, w);
        dictByLen[(int)w.size()].push_back(w);

        vector<int> p = patternOf(w);
        string key;
        for (int x : p) {
            key += to_string(x);
            key += ',';
        }
        dictByLenPattern[to_string((int)w.size()) + "#" + key].push_back(w);
    }

    string line;
    while (getline(cin, line)) {
        vector<string> words;
        {
            stringstream ss(line);
            string w;
            while (ss >> w) words.push_back(w);
        }

        vector<int> order(words.size());
        iota(order.begin(), order.end(), 0);

        auto getCandidates = [&](const string& w) -> const vector<string>& {
            static const vector<string> empty;
            vector<int> p = patternOf(w);
            string key = to_string((int)w.size()) + "#";
            for (int x : p) {
                key += to_string(x);
                key += ',';
            }
            auto it = dictByLenPattern.find(key);
            if (it == dictByLenPattern.end()) return empty;
            return it->second;
        };

        sort(order.begin(), order.end(), [&](int a, int b) {
            return getCandidates(words[a]).size() < getCandidates(words[b]).size();
        });

        vector<char> c2p(26, 0), p2c(26, 0);
        bool solved = false;

        function<bool(int)> dfs = [&](int idx) -> bool {
            if (idx == (int)order.size()) return true;

            int wi = order[idx];
            const string& cw = words[wi];
            const vector<string>& cand = getCandidates(cw);

            for (const string& pw : cand) {
                bool ok = true;
                vector<pair<int,char>> changed1, changed2;

                for (int i = 0; i < (int)cw.size(); ++i) {
                    int c = cw[i] - 'a';
                    int p = pw[i] - 'a';

                    if (c2p[c] && c2p[c] != pw[i]) { ok = false; break; }
                    if (p2c[p] && p2c[p] != cw[i]) { ok = false; break; }

                    if (!c2p[c]) {
                        c2p[c] = pw[i];
                        changed1.push_back({c, pw[i]});
                    }
                    if (!p2c[p]) {
                        p2c[p] = cw[i];
                        changed2.push_back({p, cw[i]});
                    }
                }

                if (ok && dfs(idx + 1)) return true;

                for (auto &x : changed1) c2p[x.first] = 0;
                for (auto &x : changed2) p2c[x.first] = 0;
            }

            return false;
        };

        solved = dfs(0);

        if (!solved) {
            for (char &ch : line) {
                if (ch >= 'a' && ch <= 'z') ch = '*';
            }
            cout << line << '\n';
        } else {
            string out = line;
            for (char &ch : out) {
                if (ch >= 'a' && ch <= 'z') ch = c2p[ch - 'a'] ? c2p[ch - 'a'] : '*';
            }
            cout << out << '\n';
        }
    }

    return 0;
}

