public class Decipher {
    static List<Integer>[] graph;
    static boolean[] visited;
    static List<Character> componentLetters;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        char[][] rules = new char[n][2];
        for (int i = 0; i < n; i++) {
            String line = br.readLine().trim();
            rules[i][0] = line.charAt(0);
            rules[i][1] = line.charAt(2);
        }
        String[] parts = br.readLine().trim().split(" ");
        String cipher = parts[0];
        int m = Integer.parseInt(parts[1]);
        String[] candidates = new String[m];
        for (int i = 0; i < m; i++) {
            candidates[i] = br.readLine().trim();
        }

        // Build graph of 26 letters
        graph = new ArrayList[26];
        for (int i = 0; i < 26; i++) graph[i] = new ArrayList<>();
        for (char[] rule : rules) {
            int u = rule[0] - 'a';
            int v = rule[1] - 'a';
            graph[u].add(v);
            graph[v].add(u);
        }

        // Find connected components
        visited = new boolean[26];
        int[] compId = new int[26];
        Arrays.fill(compId, -1);
        List<List<Character>> components = new ArrayList<>();

        for (int i = 0; i < 26; i++) {
            if (!visited[i]) {
                componentLetters = new ArrayList<>();
                dfs(i);
                components.add(componentLetters);
                int id = components.size() - 1;
                for (char c : componentLetters) {
                    compId[c - 'a'] = id;
                }
            }
        }

        // For each candidate, check if it can be the plaintext
        for (String candidate : candidates) {
            if (canMatch(cipher, candidate, compId, components)) {
                System.out.println(candidate);
                return;
            }
        }
    }

    static void dfs(int u) {
        visited[u] = true;
        componentLetters.add((char) (u + 'a'));
        for (int v : graph[u]) {
            if (!visited[v]) dfs(v);
        }
    }

    static boolean canMatch(String cipher, String candidate, int[] compId, List<List<Character>> components) {
        if (cipher.length() != candidate.length()) return false;
        int len = cipher.length();
        // Build mapping from cipher letter to possible plaintext letters
        // For each position we can only assign one letter from the component
        Map<Character, Character> cipherToPlain = new HashMap<>();
        Map<Character, Character> plainToCipher = new HashMap<>();

        for (int i = 0; i < len; i++) {
            char c = cipher.charAt(i);
            char p = candidate.charAt(i);
            int cComp = compId[c - 'a'];
            int pComp = compId[p - 'a'];
            if (cComp != pComp) return false;

            if (cipherToPlain.containsKey(c)) {
                if (cipherToPlain.get(c) != p) return false;
            } else {
                cipherToPlain.put(c, p);
            }
            if (plainToCipher.containsKey(p)) {
                if (plainToCipher.get(p) != c) return false;
            } else {
                plainToCipher.put(p, c);
            }
        }
        return true;
    }
}

