/*
 * Substitution-cipher deciphering by pattern matching.
 *
 * Idea:
 * A ciphertext word can come from a plaintext word if there exists a
 * one-to-one renaming of letters that transforms one into the other.
 * This is exactly "same pattern" matching.
 *
 * Example:
 *   "foo" matches "abb"
 *   because first letter is unique, next two are equal.
 *
 * For each query word, we compare it against all candidate plaintext words
 * of the same length and keep those with identical canonical pattern.
 *
 * Input format assumed:
 *   n
 *   <n candidate words>
 *   m
 *   <m ciphertext words>
 *
 * Output:
 *   For each ciphertext word:
 *     - if exactly one candidate matches, print that candidate
 *     - otherwise print "NOT UNIQUE"
 *
 * This is a robust standard solution for substitution-based word deciphering.
 */
public class Main {

    static String pattern(String s) {
        Map<Character, Integer> map = new HashMap<>();
        StringBuilder sb = new StringBuilder();
        int next = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            Integer id = map.get(c);
            if (id == null) {
                id = next++;
                map.put(c, id);
            }
            sb.append(id).append('#');
        }
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        Integer nObj = fs.nextIntNullable();
        if (nObj == null) return;
        int n = nObj;

        Map<Integer, Map<String, List<String>>> dict = new HashMap<>();

        for (int i = 0; i < n; i++) {
            String w = fs.next();
            int len = w.length();
            String p = pattern(w);
            dict.computeIfAbsent(len, k -> new HashMap<>())
                .computeIfAbsent(p, k -> new ArrayList<>())
                .add(w);
        }

        int m = fs.nextInt();
        StringBuilder out = new StringBuilder();

        for (int i = 0; i < m; i++) {
            String cipher = fs.next();
            int len = cipher.length();
            String p = pattern(cipher);

            List<String> matches = null;
            Map<String, List<String>> byPattern = dict.get(len);
            if (byPattern != null) matches = byPattern.get(p);

            if (matches != null && matches.size() == 1) {
                out.append(matches.get(0));
            } else {
                out.append("NOT UNIQUE");
            }
            if (i + 1 < m) out.append('\n');
        }

        System.out.print(out.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;

            StringBuilder sb = new StringBuilder();
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        Integer nextIntNullable() throws IOException {
            String s = next();
            if (s == null) return null;
            return Integer.parseInt(s);
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

