import sys

def can_match(cipher_word: str, plain_word: str) -> bool:
    if len(cipher_word) != len(plain_word):
        return False

    # substitution must be symmetric: if x <-> y then everywhere x maps to y and y maps to x
    mp = {}

    for c, p in zip(cipher_word, plain_word):
        if c in mp and mp[c] != p:
            return False
        if p in mp and mp[p] != c:
            return False
        mp[c] = p
        mp[p] = c

    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    out = []

    while True:
        try:
            n = int(next(it))
        except StopIteration:
            break

        candidates = [next(it) for _ in range(n)]
        m = int(next(it))
        ciphertexts = [next(it) for _ in range(m)]

        for cw in ciphertexts:
            matches = [w for w in candidates if can_match(cw, w)]
            if len(matches) == 1:
                out.append(matches[0])
            else:
                out.append("?")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
